import {space} from '@/components/nyc-tron/ui/tokens';
export interface ParametricConstraint {id:string;label:string;kind:string;expression:string;enabled:boolean;references:readonly string[];readOnly:boolean;resolvedValue?:string;error?:string}
export interface ParametricConstraintEditorProps extends Omit<ViewProps,'children'>,ScopedControlProps {constraints:readonly ParametricConstraint[];selectedId:string|null;kinds:readonly {id:string;label:string;canCreate:boolean}[];solver:{status:'dirty'|'solving'|'solved'|'conflict'|'error';revision:string|number;degreesOfFreedom:number|null;conflicts:readonly {id:string;label:string;constraintIds:readonly string[]}[]};onSelect:(id:string)=>void;onCommit:(value:ParametricConstraint,signal?:AbortSignal)=>unknown;onAdd:(kind:string,signal?:AbortSignal)=>unknown;onRemove:(id:string,signal?:AbortSignal)=>unknown;onSolve:(signal?:AbortSignal)=>unknown;onRevealConflict:(ids:readonly string[])=>void;unstyled?:boolean}
export function ParametricConstraintEditor({scope='parametric-constraints',revision=0,...props}:ParametricConstraintEditorProps){const {constraints,selectedId,kinds,solver,onSelect:_select,onCommit:_commit,onAdd:_add,onRemove:_remove,onSolve:_solve,onRevealConflict:_conflict,unstyled=false,disabledReason,style,...rest}=props;
 if(constraints.length>10000||kinds.length>64||new Set(constraints.map(c=>c.id)).size!==constraints.length||constraints.some(c=>!c.id.trim()||c.expression.length>8192||c.references.length>1024)||solver.conflicts.length>4096||solver.degreesOfFreedom!==null&&(!Number.isSafeInteger(solver.degreesOfFreedom)||solver.degreesOfFreedom<0))throw new RangeError('Invalid parametric solver state');const guard=useScopedControl(JSON.stringify([...controlIdentity(scope,revision),disabledReason]),props,disabledReason!==undefined||solver.status==='solving'),off=guard.pending||disabledReason!==undefined||solver.status==='solving',selected=constraints.find(c=>c.id===selectedId);
 return <View {...rest} style={[{gap:space[2]},style]}><FlatList style={{height:220}} data={constraints} keyExtractor={c=>c.id} renderItem={({item})=><Button title={item.label+' · '+item.kind+(item.error?' · error':'')} variant="secondary" disabled={off} accessibilityState={{selected:item.id===selectedId}} unstyled={unstyled} onPress={()=>{const h=guard.current();if(h?.constraints.some(c=>c.id===item.id))h.onSelect(item.id);}}/>}/>{selected?<><PropertyInspector scope={scope} revision={revision} label="Parametric constraint" disabledReason={off||selected.readOnly?'Constraint editing unavailable':undefined} unstyled={unstyled} fields={[{kind:'text',id:'expression',label:'Constraint expression',value:selected.expression,maxLength:8192},{kind:'boolean',id:'enabled',label:'Enabled',value:selected.enabled}]} onCommit={(id,value)=>guard.run('constraint',(h,s)=>{const c=h.constraints.find(c=>c.id===h.selectedId);if(c&&!c.readOnly)return h.onCommit({...c,[id]:value},s);})}/><Text selectable {...{className:unstyled?undefined:'text-text'}}>{'Geometry references: '+selected.references.join(', ')+'; evaluated value: '+(selected.resolvedValue??'not reported')}</Text><ErrorMessage message={selected.error} unstyled={unstyled}/><Button title="Remove selected constraint" disabled={off||selected.readOnly} unstyled={unstyled} onPress={()=>guard.run('remove',(h,s)=>h.selectedId&&h.constraints.some(c=>c.id===h.selectedId&&!c.readOnly)?h.onRemove(h.selectedId,s):undefined)}/></>:null}<View style={{flexDirection:'row',gap:space[2],flexWrap:'wrap'}}>{kinds.map(k=><Button key={k.id} title={'Add '+k.label} disabled={off||!k.canCreate} unstyled={unstyled} onPress={()=>guard.run('add',(h,s)=>h.kinds.some(v=>v.id===k.id&&v.canCreate)?h.onAdd(k.id,s):undefined)}/>)}</View><Button title="Solve parametric constraints" disabled={off} unstyled={unstyled} onPress={()=>guard.run('solve',(h,s)=>h.onSolve(s))}/><Text accessibilityLiveRegion="polite" {...{className:unstyled?undefined:'text-text'}}>{solver.status+(solver.revision!==revision?' · earlier revision':'')+'; degrees of freedom: '+(solver.degreesOfFreedom??'not reported')}</Text><FlatList style={{height:180}} data={solver.conflicts} keyExtractor={c=>c.id} renderItem={({item})=><Button title={item.label} disabled={off} unstyled={unstyled} onPress={()=>{const h=guard.current(),conflict=h?.solver.conflicts.find(c=>c.id===item.id);if(h&&conflict)h.onRevealConflict(conflict.constraintIds.filter(id=>h.constraints.some(c=>c.id===id)));}}/>}/><ErrorMessage message={guard.error??disabledReason} unstyled={unstyled}/></View>;
